CREATE TABLE `sourcing_searches` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`collection_task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`input_type` ENUM('keyword','image','opportunity','product_url') NOT NULL,`input_ref` VARCHAR(2048) NOT NULL,`status` ENUM('queued','projecting','succeeded','succeeded_empty','completed_with_warnings','failed_terminal','dead_letter') NOT NULL DEFAULT 'queued',`candidate_count` INT UNSIGNED NOT NULL DEFAULT 0,`missing_fields_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_sourcing_search_scope`(`organization_id`,`workspace_id`,`created_at`),CONSTRAINT `fk_sourcing_search_task` FOREIGN KEY(`collection_task_id`) REFERENCES `collection_tasks`(`id`),CONSTRAINT `fk_sourcing_search_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_projection_jobs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`search_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('queued','leased','retry_scheduled','succeeded','completed_with_warnings','failed_terminal','dead_letter') NOT NULL DEFAULT 'queued',`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`lease_owner` VARCHAR(120) NULL,`lease_expires_at` DATETIME(3) NULL,`last_error_code` VARCHAR(120) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_sourcing_projection_search`(`search_id`),KEY `idx_sourcing_projection_claim`(`status`,`available_at`,`lease_expires_at`),CONSTRAINT `fk_sourcing_projection_search` FOREIGN KEY(`search_id`) REFERENCES `sourcing_searches`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_candidates` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`search_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`normalized_record_id` CHAR(36) CHARACTER SET ascii NOT NULL,`raw_evidence_id` CHAR(36) CHARACTER SET ascii NOT NULL,`external_id` VARCHAR(200) CHARACTER SET ascii NOT NULL,`supplier_name` VARCHAR(500) NOT NULL,`product_title` VARCHAR(1000) NOT NULL,`specification` VARCHAR(1000) NULL,`moq` INT UNSIGNED NOT NULL,`quoted_price` DECIMAL(18,6) NOT NULL,`currency` CHAR(3) CHARACTER SET ascii NOT NULL,`lead_time_days` INT UNSIGNED NULL,`location` VARCHAR(255) NULL,`original_url` VARCHAR(2048) NOT NULL,`observed_at` DATETIME(3) NOT NULL,`confidence_value` DECIMAL(5,2) NULL,`status` ENUM('incomplete','ready','quarantined') NOT NULL DEFAULT 'incomplete',`missing_fields_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_sourcing_candidate_record`(`search_id`,`normalized_record_id`),KEY `idx_sourcing_candidate_scope`(`organization_id`,`workspace_id`,`search_id`,`status`),CONSTRAINT `fk_sourcing_candidate_search` FOREIGN KEY(`search_id`) REFERENCES `sourcing_searches`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_sourcing_candidate_record` FOREIGN KEY(`normalized_record_id`) REFERENCES `normalized_records`(`id`),CONSTRAINT `fk_sourcing_candidate_evidence` FOREIGN KEY(`raw_evidence_id`) REFERENCES `raw_evidence`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `supplier_quotes` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`candidate_id` CHAR(36) CHARACTER SET ascii NOT NULL,`quote_version` INT UNSIGNED NOT NULL,`is_current` TINYINT(1) NOT NULL DEFAULT 1,`supplier_name` VARCHAR(500) NOT NULL,`product_title` VARCHAR(1000) NOT NULL,`specification` VARCHAR(1000) NOT NULL,`moq` INT UNSIGNED NOT NULL,`quoted_price` DECIMAL(18,6) NOT NULL,`currency` CHAR(3) CHARACTER SET ascii NOT NULL,`lead_time_days` INT UNSIGNED NOT NULL,`location` VARCHAR(255) NOT NULL,`original_url` VARCHAR(2048) NOT NULL,`observed_at` DATETIME(3) NOT NULL,`evidence_id` CHAR(36) CHARACTER SET ascii NOT NULL,`confidence_value` DECIMAL(5,2) NOT NULL,`stability_status` ENUM('stable','variable','unknown') NOT NULL,`risk_level` ENUM('low','medium','high','unknown') NOT NULL,`confirmed_by` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_supplier_quote_version`(`candidate_id`,`quote_version`),KEY `idx_supplier_quote_current`(`organization_id`,`workspace_id`,`is_current`,`created_at`),CONSTRAINT `fk_supplier_quote_candidate` FOREIGN KEY(`candidate_id`) REFERENCES `sourcing_candidates`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_supplier_quote_confirmer` FOREIGN KEY(`confirmed_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_comparisons` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(200) NOT NULL,`quote_ids_json` JSON NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_sourcing_comparison_scope`(`organization_id`,`workspace_id`,`created_at`),CONSTRAINT `fk_sourcing_comparison_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_purchase_tasks` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`quote_id` CHAR(36) CHARACTER SET ascii NOT NULL,`quantity` INT UNSIGNED NOT NULL,`reason` VARCHAR(1000) NOT NULL,`status` ENUM('queued','created','failed') NOT NULL DEFAULT 'queued',`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_sourcing_purchase_delivery`(`organization_id`,`workspace_id`,`status`,`created_at`),CONSTRAINT `fk_sourcing_purchase_quote` FOREIGN KEY(`quote_id`) REFERENCES `supplier_quotes`(`id`),CONSTRAINT `fk_sourcing_purchase_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(120) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` VARCHAR(120) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_sourcing_event_scope`(`organization_id`,`workspace_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_outbox` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(120) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`status` ENUM('queued','published','dead_letter') NOT NULL DEFAULT 'queued',`available_at` DATETIME(3) NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_sourcing_outbox_ready`(`status`,`available_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sourcing_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(255) NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_sourcing_operation`(`actor_id`,`route`,`idempotency_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
